def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the silhouette made of color 1.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    shape = [[grid[r][c] == 1 for c in range(c0, c1 + 1)]
             for r in range(r0, r1 + 1)]
    sh = len(shape)

    # Find the color key: the non-silhouette group of repeated color rows/columns.
    # Its colors are the nonzero values on a row/column outside the silhouette.
    key = None
    for r in range(h):
        vals = [v for v in grid[r] if v not in (0, 1)]
        if vals:
            key = vals
            break
    if key is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h) if grid[r][c] not in (0, 1)]
            if vals:
                key = vals
                break

    # A vertical key may repeat the same sequence on consecutive rows.
    if key and len(set(key)) == 1:
        for c in range(w):
            vals = [grid[r][c] for r in range(h) if grid[r][c] != 0]
            if len(vals) > len(key) and any(v != 1 for v in vals):
                key = vals
                break

    colors = key
    if not colors:
        colors = [1]
    idx = colors.index(1) if 1 in colors else 0
    start = r0 - idx * sh

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(colors):
        for dr in range(sh):
            for dc in range(len(shape[0])):
                rr = start + i * sh + dr
                if 0 <= rr < h and shape[dr][dc]:
                    out[rr][c0 + dc] = color
    return out
